INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966225', 63966225, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi (Surat Keputusan Penetapan Hak Atas Tanah Perorangan dan Badan Hukum)', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 3208000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Penerbitan Surat Keputusan Penetapan Hak Atas Tanah Perorangan dan Badan Hukum merupakan rangkaian proses administrasi pertanahan yang bertujuan memberikan kepastian hukum atas penguasaan dan pemilikan tanah sesuai dengan ketentuan peraturan perundang-undangan. Uraian pekerjaan meliputi tahapan sebagai berikut: 1. Penerimaan dan penelitian berkas permohonan penetapan hak atas tanah dari perorangan maupun badan hukum. 2. Pemeriksaan kelengkapan dan keabsahan data yuridis dan data fisik tanah. 3. Verifikasi kesesuaian data permohonan dengan peta pendaftaran, buku tanah, dan/atau hasil pengukuran. 4. Pelaksanaan penelitian lapangan apabila diperlukan untuk memastikan kondisi fisik dan batas bidang tanah. 5. Penyusunan konsep Surat Keputusan Penetapan Hak Atas Tanah sesuai jenis hak (Hak Milik, HGU, HGB, Hak Pakai, atau hak lainnya). 6. Pemeriksaan dan pengesahan konsep SK oleh pejabat yang berwenang. 7. Penerbitan dan pencatatan Surat Keputusan Penetapan Hak Atas Tanah dalam sistem administrasi pertanahan. 8. Penyampaian SK Penetapan Hak Atas Tanah kepada pemohon sebagai dasar penerbitan sertipikat hak atas tanah.', 'Spesifikasi pekerjaan dalam kegiatan ini meliputi: 1. Subjek Hak o Perorangan Warga Negara Indonesia. o Badan Hukum Indonesia sesuai ketentuan peraturan perundang-undangan. 2. Objek Hak o Bidang tanah yang belum terdaftar atau yang memerlukan penetapan hak baru. o Tanah negara, tanah hasil pelepasan kawasan, atau tanah sesuai alas hak yang sah. 3. Jenis Dokumen yang Dihasilkan o Surat Keputusan Penetapan Hak Atas Tanah Perorangan atau Badan Hukum. o Dokumen pendukung berupa berita acara, risalah pemeriksaan tanah, dan peta bidang. 4. Standar Proses o Dilaksanakan sesuai Undang-Undang Pokok Agraria (UUPA). o Berpedoman pada peraturan pelaksana di bidang pendaftaran tanah dan penetapan hak atas tanah. o Mengikuti Standar Operasional Prosedur (SOP) Kantor Pertanahan. 5. Output Kegiatan o Terbitnya Surat Keputusan Penetapan Hak Atas Tanah yang sah, tertib administrasi, dan dapat dipertanggungjawabkan secara hukum. 6. Kriteria Keberhasilan o SK diterbitkan tepat waktu sesuai standar pelayanan. o Tidak terdapat kesalahan administrasi, data fisik, maupun data yuridis. o Memberikan kepastian hukum hak atas tanah bagi pemohon.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230159);
