INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966569', 63966569, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 15000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan SHAT PTSL ASN Kategori 3 merupakan bagian dari pelaksanaan Pendaftaran Tanah Sistematis Lengkap (PTSL) yang ditujukan untuk bidang tanah Aset Negara/Daerah (ASN) yang telah terdaftar atau memiliki alas hak, namun masih memerlukan penyelesaian administrasi lanjutan untuk penerbitan Sertipikat Hak Atas Tanah (SHAT). Kategori 3 mencakup bidang tanah yang data fisik dan/atau data yuridisnya telah tersedia, namun masih memerlukan klarifikasi, penyesuaian, atau penyempurnaan sesuai ketentuan. Uraian pekerjaan meliputi tahapan sebagai berikut: 1. Inventarisasi dan identifikasi bidang tanah ASN yang termasuk dalam PTSL Kategori 3. 2. Pengumpulan dan penelitian data yuridis berupa alas hak, dokumen penguasaan, dan status hukum tanah. 3. Pemeriksaan dan validasi data fisik berupa peta bidang, hasil pengukuran, dan batas bidang tanah. 4. Klarifikasi dan penyempurnaan data fisik dan/atau data yuridis yang belum lengkap atau belum sesuai. 5. Pelaksanaan verifikasi lapangan apabila diperlukan untuk memastikan kesesuaian data. 6. Pembukuan hak atas tanah ASN sesuai ketentuan PTSL. 7. Penerbitan Sertipikat Hak Atas Tanah (SHAT) hasil PTSL ASN Kategori 3. 8. Pencatatan dan pendokumentasian hasil kegiatan dalam sistem administrasi pertanahan.', '1. Kategori Kegiatan o PTSL ASN Kategori 3, yaitu bidang tanah yang telah memiliki data dasar namun memerlukan penyempurnaan administrasi sebelum penerbitan sertipikat. 2. Subjek Hak o Pemerintah pusat atau pemerintah daerah sebagai pemegang hak atas tanah ASN. 3. Objek Kegiatan o Bidang tanah aset negara/daerah yang termasuk lokasi PTSL. 4. Metode Pelaksanaan o Penelitian data fisik dan data yuridis. o Klarifikasi dokumen dan verifikasi lapangan terbatas. o Pembukuan hak dan penerbitan sertipikat. 5. Dokumen yang Dihasilkan o Sertipikat Hak Atas Tanah (SHAT) ASN. o Buku tanah dan surat ukur. o Berita acara verifikasi dan klarifikasi data. 6. Standar dan Ketentuan o Berpedoman pada peraturan perundang-undangan di bidang PTSL. o Mengacu pada petunjuk teknis PTSL dan pengelolaan aset negara/daerah. o Mengikuti SOP Kementerian ATR/BPN. 7. Output Kegiatan o Terbitnya SHAT PTSL ASN Kategori 3 yang sah secara hukum dan tertib administrasi. 8. Kriteria Keberhasilan o Sertipikat diterbitkan sesuai target dan ketentuan. o Data fisik dan yuridis lengkap, valid, dan dapat dipertanggungjawabkan. o Mendukung tertib administrasi dan pengamanan aset negara/daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230360);
