INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966576', 63966576, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penerbitan SK Hak/Pengesahan Data Fisik dan Yuridis ( SHAT PTSL ASN Kategori 3 )', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 4500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Penerbitan SK Hak/Pengesahan Data Fisik dan Yuridis (SHAT) PTSL ASN Kategori 3 merupakan kegiatan administrasi pertanahan dalam rangka pengesahan data fisik dan data yuridis bidang tanah hasil Pendaftaran Tanah Sistematis Lengkap (PTSL) yang memenuhi kriteria Kategori 3, sebagai dasar penerbitan sertipikat hak atas tanah. Kegiatan ini meliputi: • Penelitian dan verifikasi akhir data fisik dan data yuridis hasil PTSL; • Klarifikasi kelengkapan dokumen pendukung sesuai ketentuan Kategori 3; • Penyusunan konsep SK Hak/Pengesahan Data Fisik dan Yuridis (SHAT); • Penetapan dan penandatanganan SK oleh pejabat yang berwenang; • Pengadministrasian dan pengarsipan SK sebagai dasar penerbitan sertipikat.', 'a. Kriteria Kategori 3 • Data fisik dan/atau data yuridis memenuhi syarat untuk disahkan; • Tidak terdapat sengketa, konflik, atau perkara; • Bidang tanah dapat diterbitkan sertipikat setelah pengesahan data. b. Ketentuan Pelaksanaan • Pemeriksaan data fisik mengacu pada peta bidang tanah hasil PTSL; • Pemeriksaan data yuridis mengacu pada alas hak, surat pernyataan, dan dokumen pendukung; • Proses pengesahan dan penetapan dilaksanakan sesuai SOP PTSL ASN; • Kewenangan penetapan mengikuti ketentuan peraturan perundang-undangan. c. Output/Hasil • SK Hak/Pengesahan Data Fisik dan Yuridis (SHAT); • Dokumen pengesahan sebagai dasar penerbitan Sertipikat Hak Atas Tanah; • Arsip administrasi pertanahan dalam bentuk fisik dan/atau digital. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang PTSL; • Petunjuk Teknis PTSL ASN yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230388);
