INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966142', 63966142, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi (Pelaksanaan Pembinaan, Monitoring dan Evaluasi)', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 2662000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Pelaksanaan Pembinaan, Monitoring, dan Evaluasi merupakan kegiatan pengendalian dan peningkatan kualitas pelaksanaan program dan kegiatan melalui pembinaan teknis dan administratif, pemantauan pelaksanaan, serta evaluasi capaian kinerja agar sesuai dengan ketentuan, standar, dan target yang telah ditetapkan. Kegiatan ini meliputi: • Pembinaan teknis dan administratif kepada pelaksana kegiatan; • Monitoring pelaksanaan kegiatan secara berkala; • Evaluasi capaian output, outcome, dan kendala pelaksanaan; • Penyusunan rekomendasi dan tindak lanjut perbaikan; • Penyusunan laporan hasil pembinaan, monitoring, dan evaluasi.', 'a. Ruang Lingkup • Pembinaan teknis dan administrasi; • Monitoring progres fisik dan nonfisik; • Evaluasi kinerja dan kepatuhan terhadap regulasi; • Tindak lanjut hasil evaluasi. b. Ketentuan Pelaksanaan • Dilaksanakan sesuai rencana dan jadwal yang ditetapkan; • Mengacu pada pedoman teknis dan SOP yang berlaku; • Dilaksanakan secara objektif, transparan, dan akuntabel; • Melibatkan pihak terkait sesuai kebutuhan. c. Output/Hasil • Laporan Pembinaan, Monitoring, dan Evaluasi; • Rekapitulasi hasil monitoring dan evaluasi; • Rekomendasi dan rencana tindak lanjut; • Dokumentasi kegiatan. d. Dasar Hukum • Peraturan perundang-undangan terkait pelaksanaan program/kegiatan; • Pedoman teknis dan SOP pelaksanaan pembinaan, monitoring, dan evaluasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230412);
