INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966498', 63966498, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 1440000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Penyusunan Laporan Hasil Sidang Perkara Pertanahan di Daerah merupakan proses pendokumentasian dan pelaporan pelaksanaan persidangan perkara pertanahan yang melibatkan instansi pertanahan sebagai pihak atau turut pihak di pengadilan. Kegiatan ini bertujuan menyediakan informasi yang akurat, tertib administrasi, serta sebagai bahan evaluasi dan pengambilan kebijakan di bidang penanganan perkara pertanahan. Uraian pekerjaan meliputi tahapan sebagai berikut: 1. Inventarisasi perkara pertanahan yang disidangkan di wilayah daerah/kabupaten/kota. 2. Pengumpulan data dan dokumen perkara, termasuk surat gugatan, jawaban, replik, duplik, dan kesimpulan. 3. Pemantauan dan pencatatan jalannya persidangan pada setiap tahapan sidang. 4. Dokumentasi hasil persidangan, termasuk keterangan para pihak, saksi, dan ahli. 5. Pencatatan putusan sela dan/atau putusan akhir pengadilan. 6. Analisis hasil sidang dan implikasinya terhadap administrasi pertanahan. 7. Penyusunan laporan hasil sidang perkara pertanahan secara sistematis dan kronologis. 8. Penyampaian laporan kepada pimpinan sebagai bahan evaluasi dan tindak lanjut.', '1. Ruang Lingkup Kegiatan o Perkara pertanahan yang ditangani dan disidangkan di wilayah daerah. o Perkara pada tingkat pengadilan pertama dan/atau tingkat lanjutan sesuai kewenangan. 2. Objek Pelaporan o Perkara sengketa hak atas tanah. o Perkara tumpang tindih bidang tanah. o Perkara pembatalan sertipikat atau penetapan hak atas tanah. 3. Sumber Data dan Dokumen o Dokumen resmi pengadilan. o Berita acara persidangan. o Data fisik dan yuridis pertanahan. 4. Metode Penyusunan Laporan o Kompilasi dan verifikasi dokumen perkara. o Analisis administratif dan yuridis pertanahan. 5. Dokumen yang Dihasilkan o Laporan hasil sidang perkara pertanahan di daerah. o Rekapitulasi status dan perkembangan perkara. 6. Standar dan Ketentuan o Mengacu pada peraturan perundang-undangan di bidang pertanahan. o Berpedoman pada SOP penanganan perkara pertanahan Kementerian ATR/BPN. 7. Output Kegiatan o Tersusunnya laporan hasil sidang perkara pertanahan yang lengkap, akurat, dan dapat dipertanggungjawabkan. 8. Kriteria Keberhasilan o Laporan disusun tepat waktu dan sesuai format. o Informasi yang disajikan jelas, kronologis, dan mendukung pengambilan keputusan. o Menjadi dasar tindak lanjut penanganan perkara pertanahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230497);
