INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966153', 63966153, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi (PBT Redistribusi Tanah Kategori Luar Jawa Bali)', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 2880000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'PBT Redistribusi Tanah Kategori Luar Jawa–Bali merupakan kegiatan pendaftaran dan pendataan bidang tanah objek redistribusi tanah melalui pengumpulan data fisik dan data yuridis secara sistematis sesuai ketentuan peraturan perundang-undangan. Kegiatan ini bertujuan untuk menyediakan data bidang tanah yang akurat dan lengkap sebagai dasar penetapan objek dan subjek redistribusi tanah, penerbitan Surat Keputusan Redistribusi Tanah, serta penerbitan sertipikat hak atas tanah. Kegiatan meliputi: • Persiapan dan identifikasi objek redistribusi tanah; • Pengumpulan data fisik bidang tanah; • Pengumpulan dan verifikasi data yuridis; • Pendataan dan inventarisasi bidang tanah; • Penyusunan dan penyampaian hasil kegiatan', 'a. Ruang Lingkup • Pengukuran dan pemetaan bidang tanah objek redistribusi; • Pengumpulan data yuridis calon penerima redistribusi; • Pendataan PBT bidang tanah; • Pengolahan dan validasi data fisik dan yuridis; • Penyusunan dokumen hasil kegiatan. b. Ketentuan Pelaksanaan • Dilaksanakan sesuai ketentuan Redistribusi Tanah Kategori Luar Jawa–Bali; • Mengacu pada peraturan perundang-undangan di bidang pertanahan; • Dilaksanakan secara transparan, akuntabel, dan partisipatif; • Data harus akurat, lengkap, dan dapat dipertanggungjawabkan; • Berkoordinasi dengan pemerintah daerah dan pihak terkait. c. Output/Hasil • Data PBT Redistribusi Tanah; • Dokumen data fisik dan yuridis bidang tanah; • Rekapitulasi objek redistribusi tanah; • Laporan pelaksanaan kegiatan. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 tentang UUPA; • Peraturan Pemerintah Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • Peraturan Menteri ATR/BPN tentang Redistribusi Tanah; • Petunjuk teknis pelaksanaan Redistribusi Tanah Kategori Luar Jawa–Bali.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230556);
