INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966058', 63966058, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of IHK Set', 'Barang', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 461498286000, 'October 2024', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '261 RS 261 Alkes', 'Pengadaan IHK Set: Lot 1: Procurement of Immunohistochemistry Set (West), Lot 2: Procurement of Immunohistochemistry Set (Central), Lot 3: Procurement of Immunohistochemistry Set (East - Maluku & Sulawesi), Lot 4: Procurement of Immunohistochemistry Set (East - Bali, Nusa Tenggara & Papua), (Paket masih dalam proses pengadaan)', 'Merupakan satu set peralatan lengkap yang dirancang untuk prosedur imunohistokimia. Paket ini mencakup: A. Mikrotom: Instrumen presisi yang digunakan untuk memotong jaringan menjadi irisan yang sangat tipis. B. Hot Plate: Perangkat untuk memanaskan kaca objek (slide) guna membantu perlekatan jaringan atau proses lain yang memerlukan pemanasan dalam imunohistokimia. C. Cold Plate: Digunakan untuk mendinginkan blok parafin, yang membantu dalam proses perlakuan jaringan tertentu. D. Tissue Floating Bath: Digunakan untuk mengapungkan dan meratakan irisan jaringan sebelum dipindahkan ke kaca objek. E. Lemari Pendingin Reagen: Lemari pendingin khusus untuk menyimpan reagen imunohistokimia yang sensitif pada suhu terkontrol. F. Mesin Pewarna Imunohistokimia Otomatis: Perangkat yang mengotomatisasi aplikasi antibodi pada sampel jaringan untuk deteksi antigen yang presisi, yang sangat penting dalam diagnosis penyakit, khususnya kanker. Mesin ini memastikan konsistensi, akurasi, dan pemrosesan berkapasitas tinggi, sehingga secara signifikan mengurangi kesalahan manual dan meningkatkan efisiensi alur kerja laboratorium. Peralatan ini merupakan instrumen penting dalam patologi modern untuk praktik diagnostik yang andal dan efisien.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230584);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63925296', 63925296, 'analyze_legacy', 'Kota Pare Pare', 'kabkota', 'SEKRETARIAT DPRD', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Suvenir/Cendera Mata', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Pare-Pare (Kota)', 10132000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Suvenir/Cendera Mata;', 'Karangan Bunga;', 10132000, 'high', 'Pengadaan suvenir/cendera mata berupa karangan bunga oleh sekretariat legislatif memiliki urgensi pelayanan publik yang lemah dan berpotensi bersifat seremonial. Seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan karena manfaat langsung bagi fungsi utama kelembagaan tidak jelas dari informasi yang tersedia.', NULL, NULL, 3, 1, 1, 1, 1, 1230585);
