INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966191', 63966191, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi (Berita Acara Penyuluhan Luar Jawa Bali)', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 1784000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '1 paket', 'Berita Acara Penyuluhan PBT PTSL Desa/Kelurahan Lengkap Kategori Luar Jawa–Bali merupakan dokumen resmi yang disusun sebagai bukti pelaksanaan kegiatan penyuluhan kepada masyarakat desa/kelurahan dalam rangka Pendaftaran Bidang Tanah (PBT) melalui Program Pendaftaran Tanah Sistematis Lengkap (PTSL). Penyusunan Berita Acara ini bertujuan untuk mendokumentasikan pelaksanaan penyuluhan, termasuk waktu, tempat, peserta, materi, serta hasil kegiatan sebagai dasar pertanggungjawaban administrasi dan bahan evaluasi pelaksanaan PTSL. Kegiatan meliputi: • Pencatatan identitas kegiatan penyuluhan; • Pendataan peserta dan narasumber; • Perumusan materi dan hasil penyuluhan; • Pengesahan dan penandatanganan Berita Acara oleh pihak terkait.', 'a. Ruang Lingkup • Penyusunan Berita Acara Penyuluhan PBT PTSL; • Pencatatan waktu, tempat, dan lokasi desa/kelurahan; • Pencantuman materi penyuluhan PTSL; • Perumusan hasil dan kesimpulan kegiatan; • Pengesahan dokumen. b. Ketentuan Pelaksanaan • Disusun sesuai format dan pedoman PTSL yang berlaku; • Mengacu pada peraturan perundang-undangan di bidang pendaftaran tanah; • Memuat data yang akurat, lengkap, dan dapat dipertanggungjawabkan; • Ditandatangani oleh petugas PTSL dan perwakilan pemerintah desa/kelurahan. c. Output/Hasil • Berita Acara Penyuluhan PBT PTSL Desa/Kelurahan Lengkap yang sah; • Daftar hadir peserta; • Materi penyuluhan; • Dokumentasi kegiatan (foto dan notulen). d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 tentang Peraturan Dasar Pokok-Pokok Agraria; • Peraturan Menteri ATR/BPN tentang Pendaftaran Tanah Sistematis Lengkap (PTSL); • Petunjuk teknis pelaksanaan PBT PTSL Desa/Kelurahan Lengkap Kategori Luar Jawa–Bali.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1230996);
