INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63965787', 63965787, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of SPECT CT', 'Barang', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 118633938000, 'October 2024', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '6 RS 6 Alkes', 'Procurement of SPECT-CT : Lot 1: Procurement of SPECT-CT dan Lot 2: Procurement of SPECT-CT. (Paket masih dalam proses pengadaan)', 'Sistem pemindaian yang dirancang untuk mengombinasikan kemampuan tomografi terkomputasi (CT), yang sering kali berupa CT helikal multislice, dengan kemampuan sistem tomografi emisi foton tunggal (SPECT). Sistem gabungan ini menggunakan pencitraan SPECT untuk mendeteksi kelainan metabolik dan pemindaian CT untuk melokalisasi lesi di dalam tubuh. Kombinasi ini memungkinkan perolehan citra fusi (yaitu integrasi) informasi anatomi dan fungsional (molekuler) melalui beberapa pemindaian dalam satu prosedur, dengan hasil yang lebih baik dibandingkan apabila kedua citra diperoleh secara terpisah. Sistem gabungan CT/SPECT dimaksudkan untuk memfasilitasi evaluasi yang lebih cepat dan lebih akurat, serta terutama digunakan untuk diagnosis, perencanaan terapi, dan evaluasi respons pengobatan pada pasien kardiologi, ortopedi, dan onkologi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1231486);
