INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63924199', 63924199, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI KOTA TIMIKA KABUPATEN MIMIKA 01', 'Pengadaan Jasa Internet', 'Jasa Lainnya', 'E-Purchasing', 'Papua Tengah, Mimika (Kab.)', 216000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bln', 'Internet Dedicated/Bandwidth 50 Mbps Backup internet broadband Ya, Minimal 50 Mbps Ratio Upstream:Downstream 1:1 SLA (Service Level Agreement) 98% Media Akses FO (Fiber Optic) Helpdesk Support 24x7 IP Publik dengan network /29 Ya Penyediaan Perangkat Router, Server, Perangkat Oudoor (ODU), Perangkat Indoor (IDU) dan perangkat Akses Point (ONT)', '1. Penyedia wajib menyediakan dan mengaktifkan layanan Internet Dedicated dalam kondisi baik, stabil, dan siap dioperasionalkan tanpa kendala di lokasi yang ditentukan paling lambat pada tanggal mulai kontrak. 2. Penyedia wajib menyediakan layanan internet sesuai dengan spesifikasi teknis produk yang ditetapkan, yaitu minimum bandwidth dedicated 50 Mbps, rasio upstream dan downstream 1:1, mendapatkan IP Publik, jangkauan layanan nasional, serta Service Level Agreement (SLA) minimum 98%. 3. Penyedia menjamin ketersediaan dan keandalan seluruh infrastruktur jaringan pendukung, termasuk backbone fiber optik, lastmile akses, perangkat jaringan, sistem monitoring, dan sistem keamanan jaringan selama masa kontrak. 4. Penyedia bertanggung jawab penuh atas kualitas, stabilitas, dan kontinuitas layanan internet selama 24 (dua puluh empat) jam nonstop setiap hari, termasuk hari libur. 5. Penyedia wajib menyediakan layanan dukungan teknis, pemeliharaan, dan perbaikan (support & maintenance) selama masa kontrak, baik secara online maupun onsite apabila diperlukan. 6. Penyedia wajib menyediakan layanan call center atau hotline 24 x 7 yang dapat dihubungi setiap waktu untuk pelaporan gangguan, permintaan bantuan teknis, dan koordinasi operasional. 7. Penyedia wajib menyediakan sistem trouble ticketing yang terdokumentasi dengan jelas, termasuk mekanisme eskalasi penanganan gangguan hingga layanan kembali normal. 8. Setiap laporan gangguan layanan internet wajib direspons dan ditindaklanjuti paling lama 3 x 24 jam sejak laporan diterima oleh Penyedia. 9. Dalam hal terjadi gangguan yang menyebabkan penurunan kualitas atau terhentinya layanan internet, Penyedia wajib melakukan perbaikan secepat mungkin sesuai dengan ketentuan SLA yang berlaku. 10. Penyedia wajib menyediakan fasilitas monitoring utilisasi bandwidth yang dapat diakses oleh pengguna untuk memantau penggunaan jaringan secara langsung (real-time). 11. Penyedia wajib menyusun dan menyampaikan laporan bulanan kepada Pejabat Pembuat Komitmen (PPK) yang memuat sekurang-kurangnya informasi kinerja layanan, tingkat pemenuhan SLA, penggunaan bandwidth (traffic), serta rekapitulasi gangguan dan penanganannya. 12. Penyedia wajib memiliki dan menjaga keabsahan izin penyelenggaraan jasa akses internet (ISP) selama masa kontrak. 13. Penyedia wajib memiliki sertifikat sistem manajemen mutu dan layanan yang masih berlaku, antara lain ISO 9001:2015, ISO 20000-1:2018, ISO 22301:2019, ISO 27001:2022, ISO 27701:2019, dan ISO 37001:2016. 14. Penyedia wajib menyediakan kontak layanan gangguan berupa nomor hotline dan/atau alamat email resmi yang dapat dihubungi 24 jam nonstop setiap hari. 15. Seluruh biaya yang timbul terkait penyediaan layanan, termasuk biaya sewa port bandwidth, sewa akses lastmile, dukungan teknis, perangkat pendukung jaringan, sistem monitoring, dan pajak menjadi tanggung jawab Penyedia sesuai dengan ketentuan kontrak. 16. Penyedia wajib menjamin keberlangsungan layanan selama masa kontrak, termasuk menyediakan solusi teknis alternatif apabila terjadi kondisi darurat yang berpotensi mengganggu layanan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1231889);
