INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966166', 63966166, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi (PBT PTSL Desa/Kelurahan Lengkap Luar Jawa Bali Pihak Ketiga)', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 4000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '1 paket', 'Partisipasi Masyarakat dalam PBT PTSL Desa/Kelurahan Lengkap Kategori Luar Jawa–Bali oleh Pihak Ketiga merupakan keterlibatan aktif masyarakat dalam mendukung pelaksanaan pengumpulan data fisik dan data yuridis bidang tanah secara sistematis dan lengkap. Kegiatan ini bertujuan untuk mempercepat pelaksanaan PTSL, meningkatkan akurasi data, memperkuat validitas batas bidang tanah, serta menumbuhkan kesadaran dan kepemilikan masyarakat terhadap tertib administrasi pertanahan. Kegiatan meliputi: • Keterlibatan masyarakat dalam penunjukan dan penetapan batas bidang tanah; • Penyediaan dan kelengkapan dokumen yuridis oleh pemilik/penguasaan tanah; • Kehadiran masyarakat dalam kegiatan pengukuran dan pendataan; • Pemberian informasi dan klarifikasi data bidang tanah; • Dukungan masyarakat terhadap kelancaran kegiatan PTSL.', 'a. Ruang Lingkup • Partisipasi masyarakat dalam penetapan dan pemasangan tanda batas; • Pendampingan kegiatan pengukuran dan pendataan PBT; • Penyampaian dokumen yuridis bidang tanah; • Klarifikasi data fisik dan yuridis oleh pemilik tanah dan saksi. b. Ketentuan Pelaksanaan • Dilaksanakan sesuai pedoman PTSL dan ketentuan ATR/BPN; • Difasilitasi oleh pihak ketiga di bawah pengawasan Kantor Pertanahan; • Dilaksanakan secara sukarela, partisipatif, dan bertanggung jawab; • Menjunjung prinsip transparansi, akurasi, dan kepastian hukum; • Menghindari konflik dan sengketa antar pemilik bidang tanah. c. Output/Hasil • Terlaksananya partisipasi masyarakat dalam kegiatan PBT PTSL; • Data fisik dan yuridis yang didukung oleh kehadiran dan persetujuan masyarakat; • Berita acara dan/atau daftar partisipasi masyarakat; • Dokumentasi kegiatan partisipasi masyarakat. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 tentang UUPA; • Peraturan Pemerintah Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • Peraturan Menteri ATR/BPN tentang PTSL; • Petunjuk teknis PBT PTSL Desa/Kelurahan Lengkap Kategori Luar Jawa–Bali.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1232062);
