INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63965480', 63965480, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of CT Simulator', 'Barang', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 41917986000, 'October 2024', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '7 RS 7 Alkes', 'Pengadaan CT Simulator : Lot 1: Procurement of CT Simulator dan Lot 2: Procurement of CT Simulator. (Paket masih dalam proses pengadaan).', 'Sistem pemindaian yang dirancang untuk mengombinasikan kemampuan tomografi terkomputasi (CT), yang sering kali berupa CT helikal multislice, dengan kemampuan sistem tomografi emisi foton tunggal (SPECT). Sistem gabungan ini menggunakan pencitraan SPECT untuk mendeteksi kelainan metabolik dan pemindaian CT untuk melokalisasi lesi di dalam tubuh. Kombinasi ini memungkinkan perolehan citra fusi (yaitu integrasi) informasi anatomi dan fungsional (molekuler) melalui beberapa pemindaian dalam satu prosedur, dengan hasil yang lebih baik dibandingkan apabila kedua citra diperoleh secara terpisah. Sistem gabungan CT/SPECT dimaksudkan untuk memfasilitasi evaluasi yang lebih cepat dan lebih akurat, serta terutama digunakan untuk diagnosis, perencanaan terapi, dan evaluasi respons pengobatan pada pasien kardiologi, ortopedi, dan onkologi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1232091);
