INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966316', 63966316, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penerbitan SK Redistribusi Tanah', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 400000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Penerbitan Surat Keputusan Redistribusi Tanah merupakan kegiatan administrasi pertanahan dalam rangka penetapan pemberian Hak Milik atas tanah negara kepada subjek penerima redistribusi tanah yang telah ditetapkan, sebagai bagian dari pelaksanaan program Reforma Agraria. Kegiatan ini meliputi: 1. Penelitian akhir data objek dan subjek redistribusi tanah; 2. Penyusunan konsep Surat Keputusan Redistribusi Tanah; 3. Penetapan dan penandatanganan SK oleh pejabat yang berwenang; 4. Pengadministrasian, pengarsipan, dan penyampaian SK; 5. Penyiapan SK sebagai dasar pendaftaran tanah dan penerbitan Sertipikat Hak Milik.', 'a. Persyaratan Objek dan Subjek • Objek: tanah negara yang telah ditetapkan sebagai objek redistribusi tanah; • Subjek: Warga Negara Indonesia yang telah ditetapkan sebagai penerima redistribusi tanah; • Data objek dan subjek telah diverifikasi dan dinyatakan memenuhi syarat. b. Ketentuan Pelaksanaan • Penyusunan SK berdasarkan hasil penetapan objek dan subjek redistribusi tanah; • SK memuat identitas subjek, data fisik bidang tanah, luas, dan letak tanah; • Penetapan dilakukan sesuai kewenangan pejabat pertanahan; • Pelaksanaan berpedoman pada SOP dan peraturan ATR/BPN yang berlaku. c. Output/Hasil • Surat Keputusan Redistribusi Tanah yang sah; • Dokumen SK sebagai dasar penerbitan Sertipikat Hak Milik; • Arsip administrasi pertanahan dalam bentuk fisik dan/atau digital. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 18 Tahun 2021; • Peraturan Presiden Nomor 62 Tahun 2023 tentang Percepatan Reforma Agraria; • Peraturan Menteri ATR/BPN terkait Redistribusi Tanah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1232520);
