INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966517', 63966517, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Layanan Pendaftaran Tanah Pertama Kali', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 1300000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Layanan Pendaftaran Tanah Pertama Kali merupakan rangkaian kegiatan administrasi dan teknis pertanahan untuk mendaftarkan bidang tanah yang belum pernah terdaftar pada Kantor Pertanahan, guna memberikan kepastian hukum dan perlindungan hukum kepada pemegang hak atas tanah melalui penerbitan sertipikat. Kegiatan ini meliputi: • Penerimaan dan pemeriksaan berkas permohonan; • Pengumpulan dan penelitian data yuridis; • Pengukuran dan pemetaan bidang tanah; • Pengumuman data fisik dan data yuridis; • Penetapan hak atas tanah; • Penerbitan dan penyerahan Sertipikat Hak Atas Tanah.', 'a. Objek dan Subjek • Objek: bidang tanah yang belum terdaftar; • Subjek: perorangan WNI dan/atau badan hukum yang memenuhi persyaratan. b. Jenis Hak • Hak Milik; • Hak Guna Bangunan; • Hak Guna Usaha; • Hak Pakai (sesuai ketentuan). c. Ketentuan Pelaksanaan • Pengukuran dilakukan sesuai standar teknis pengukuran dan pemetaan; • Penelitian data yuridis berdasarkan alas hak dan riwayat tanah; • Proses pendaftaran dilaksanakan sesuai SOP ATR/BPN; • Pelayanan dilaksanakan secara transparan, akuntabel, dan tepat waktu. d. Output/Hasil • Sertipikat Hak Atas Tanah; • Buku Tanah; • Surat Ukur/Peta Bidang Tanah; • Arsip administrasi pertanahan (fisik dan/atau digital). e. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang Pendaftaran Tanah; • SOP Layanan Pendaftaran Tanah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1233073);
