INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63945860', 63945860, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pelayanan Umum, Pelayanan Rumah Tangga dan Perlengkapan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 22505000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan pelayanan umum, pelayanan rumah tangga, dan perlengkapan dilaksanakan untuk mendukung kelancaran operasional perkantoran melalui penyediaan layanan umum, pengelolaan rumah tangga kantor, serta pemenuhan kebutuhan perlengkapan kerja. Ruang lingkup kegiatan meliputi: 1. Pelayanan umum dalam mendukung kegiatan administrasi dan pelayanan kantor. 2. Pengelolaan rumah tangga kantor, termasuk kebersihan, kerapian, dan kenyamanan lingkungan kerja. 3. Penyediaan, pengelolaan, dan pemeliharaan perlengkapan kantor. 4. Dukungan logistik untuk kegiatan perkantoran dan kedinasan. Kegiatan ini bertujuan untuk menciptakan lingkungan kerja yang tertib, nyaman, dan mendukung produktivitas pegawai serta kualitas pelayanan kepada masyarakat.', 'Pelayanan Umum, Pelayanan Rumah Tangga, dan Perlengkapan 1. Pelayanan Umum o Mendukung kelancaran administrasi dan kegiatan perkantoran. o Menyediakan layanan pendukung kegiatan rapat, pertemuan, dan kedinasan. o Menjaga ketertiban dan kenyamanan pelayanan di lingkungan kantor. 2. Pelayanan Rumah Tangga o Menjaga kebersihan ruang kerja, ruang pelayanan, dan fasilitas pendukung. o Menata dan merawat lingkungan kantor agar tetap rapi dan layak fungsi. o Mendukung kesiapan sarana prasarana untuk kegiatan perkantoran. 3. Perlengkapan o Menyediakan dan mengelola perlengkapan kantor sesuai kebutuhan operasional. o Melakukan pencatatan, penyimpanan, dan pengendalian perlengkapan kantor. o Melakukan pemeliharaan ringan perlengkapan agar tetap layak pakai. 4. Standar Pelaksanaan o Dilaksanakan sesuai ketentuan peraturan perundang-undangan. o Tidak mengganggu aktivitas pelayanan dan operasional kantor. o Mengutamakan efektivitas, efisiensi, dan akuntabilitas. 5. Hasil yang Diharapkan o Terlaksananya pelayanan umum dan rumah tangga kantor secara tertib. o Tersedianya perlengkapan kantor yang memadai dan siap digunakan. o Terciptanya lingkungan kerja yang bersih, nyaman, dan mendukung produktivitas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1233440);
