INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966534', 63966534, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pemeliharaan Data Pendaftaran Tanah', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 400000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pemeliharaan Data Pendaftaran Tanah merupakan kegiatan pelayanan pertanahan yang dilakukan untuk memperbarui, menyesuaikan, dan menjaga keakuratan data fisik dan/atau data yuridis pendaftaran tanah akibat adanya perubahan kondisi hukum maupun fisik atas suatu bidang tanah yang telah terdaftar. Kegiatan ini bertujuan untuk menjamin tertib administrasi dan kepastian hukum data pertanahan. Kegiatan ini meliputi: • Penerimaan dan pemeriksaan permohonan pemeliharaan data; • Penelitian data yuridis dan/atau data fisik; • Pencatatan perubahan pada buku tanah dan peta pendaftaran; • Penerbitan dokumen hasil pemeliharaan data; • Pengarsipan dan pemutakhiran basis data pertanahan.', 'a. Ruang Lingkup Pemeliharaan Data • Peralihan hak (jual beli, hibah, waris, tukar menukar); • Pembebanan hak (Hak Tanggungan); • Perubahan data subjek dan/atau objek hak; • Pemecahan, penggabungan, pemisahan, dan pengukuran ulang bidang tanah; • Perpanjangan dan pembaruan hak. b. Ketentuan Pelaksanaan • Dilaksanakan sesuai SOP dan ketentuan pendaftaran tanah; • Data pendukung harus sah dan dapat dipertanggungjawabkan; • Perubahan dicatat secara lengkap dan akurat dalam sistem pendaftaran tanah; • Pelayanan dilaksanakan secara transparan dan akuntabel. c. Output/Hasil • Sertipikat hak atas tanah hasil pemeliharaan data (jika diperlukan); • Buku tanah dan surat ukur yang telah diperbarui; • Peta pendaftaran yang telah dimutakhirkan; • Arsip administrasi pertanahan fisik dan/atau digital. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang Pendaftaran Tanah; • SOP Pemeliharaan Data Pendaftaran Tanah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1233734);
