INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966200', 63966200, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of Brachytherapy', 'Barang', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 26809288000, 'October 2024', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '9 RS 9 Alkes', 'Pengadaan Brachytherapy: Lot 1: Procurement of Brachytherapy dan Lot 2: Procurement of Brachytherapy (Paket masih dalam proses pengadaan).', 'Sistem Brachytheraphy yang dirancang untuk pengantaran radioisotop secara otomatis, umumnya iridium-192, langsung ke dalam jaringan kanker. Sistem ini biasanya berupa unit pengantaran radioisotop (yaitu unit afterloading) yang dilengkapi dengan mekanisme penggerak sumber (biasanya motor stepper yang dikendalikan komputer dengan rol atau sabuk penggerak), brankas berpelindung, aplikator, konsol kendali, serta unit perencanaan berbasis komputer. Sistem Brachytheraphy dapat mencakup modul perencanaan terapi, meja perawatan bermotor dengan pergerakan tiga dimensi (X, Y, dan Z), serta kemampuan pencitraan sinar-X, sehingga sistem perencanaan terapi terintegrasi sepenuhnya untuk pembaruan distribusi dosis secara langsung. Isotop radiasi dihantarkan menggunakan aplikator khusus untuk rongga tubuh tertentu atau melalui jarum, tabung, atau kateter sekali pakai untuk pengantaran interstisial. Sistem remote afterloading umum digunakan untuk menangani berbagai jenis kanker, termasuk kanker endometrium, serviks, pankreas, dan endobronkial.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1233787);
