INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63946041', 63946041, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pengelolaan Pengaduan dan Pelayanan Informasi Publik', 'Jasa Lainnya', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 21520000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan pengelolaan pengaduan dan pelayanan informasi publik dilaksanakan untuk menjamin pemenuhan hak masyarakat atas pengaduan dan akses informasi serta meningkatkan transparansi, akuntabilitas, dan kualitas pelayanan publik. Ruang lingkup kegiatan meliputi: 1. Penerimaan dan pencatatan pengaduan masyarakat. 2. Penanganan, koordinasi, dan tindak lanjut pengaduan sesuai ketentuan. 3. Pelayanan permohonan informasi publik. 4. Penyediaan dan penyampaian informasi publik yang akurat dan dapat diakses. 5. Dokumentasi dan pelaporan hasil pengelolaan pengaduan dan pelayanan informasi.', '1. Pengelolaan Pengaduan a. Menerima pengaduan melalui media yang tersedia (langsung, tertulis, dan/atau daring). b. Mencatat dan mengklasifikasikan pengaduan sesuai jenis dan substansi. c. Menyampaikan pengaduan kepada unit terkait untuk ditindaklanjuti. d. Memantau dan mendokumentasikan tindak lanjut pengaduan. 2. Pelayanan Informasi Publik a. Melayani permohonan informasi publik sesuai ketentuan peraturan perundang-undangan. b. Menyediakan informasi publik yang dikuasai dan dapat dibuka untuk umum. c. Mengelola arsip dan dokumentasi informasi publik. d. Menyampaikan informasi secara tepat waktu dan akurat. 3. Standar Pelaksanaan a. Dilaksanakan sesuai ketentuan keterbukaan informasi publik dan pelayanan pengaduan. b. Menjaga kerahasiaan data pribadi dan informasi yang dikecualikan. c. Mengutamakan prinsip transparansi, akuntabilitas, dan responsivitas. 4. Hasil yang Diharapkan a. Tertanganinya pengaduan masyarakat secara tertib dan tepat waktu. b. Tersedianya pelayanan informasi publik yang transparan dan akuntabel. c. Meningkatnya kepercayaan masyarakat terhadap pelayanan instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1233962);
