INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966312', 63966312, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penetapan Objek dan Subjek Redistribusi Tanah', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 1000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Penetapan Objek dan Subjek Redistribusi Tanah merupakan kegiatan identifikasi, verifikasi, dan penetapan terhadap tanah negara yang memenuhi syarat sebagai objek redistribusi tanah serta penetapan subjek penerima redistribusi tanah sesuai ketentuan peraturan perundang-undangan dalam rangka pelaksanaan Reforma Agraria. Kegiatan ini meliputi: 1. Inventarisasi dan identifikasi tanah negara calon objek redistribusi tanah; 2. Verifikasi penguasaan, penggunaan, dan pemanfaatan tanah; 3. Pendataan dan seleksi calon subjek penerima redistribusi tanah; 4. Penyesuaian data dengan ketentuan tata ruang dan kebijakan Reforma Agraria; 5. Penyusunan dan penetapan dokumen penetapan objek dan subjek redistribusi tanah.', 'a. Objek Redistribusi Tanah • Tanah negara yang berasal dari: o Tanah bekas HGU; o Tanah terlantar; o Tanah negara lainnya yang sah menurut ketentuan; • Tidak dalam sengketa dan tidak tumpang tindih; • Sesuai dengan rencana tata ruang wilayah. b. Subjek Redistribusi Tanah • Warga Negara Indonesia yang memenuhi kriteria penerima redistribusi tanah; • Berdomisili di sekitar lokasi objek tanah; • Memenuhi persyaratan sosial, ekonomi, dan yuridis sesuai ketentuan. c. Ketentuan Pelaksanaan • Verifikasi data fisik berdasarkan hasil pengukuran lapangan dan peta bidang; • Verifikasi data yuridis berdasarkan alas hak, riwayat tanah, dan penguasaan fisik; • Penetapan dilakukan secara transparan dan akuntabel; • Berpedoman pada ketentuan Reforma Agraria dan SOP ATR/BPN. d. Output/Hasil • Dokumen Penetapan Objek dan Subjek Redistribusi Tanah; • Daftar nominatif subjek redistribusi tanah; • Peta objek redistribusi tanah; • Arsip administrasi pertanahan (fisik dan/atau digital). e. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 18 Tahun 2021; • Peraturan Presiden Nomor 62 Tahun 2023 tentang Percepatan Reforma Agraria; • Peraturan Menteri ATR/BPN terkait Redistribusi Tanah dan Reforma Agraria.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1234591);
