INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966343', 63966343, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pelaporan Pembaruan Peta Zona Nilai Tanah', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 2550000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pelaporan Pembaruan Peta Zona Nilai Tanah merupakan kegiatan penyusunan dan penyampaian laporan hasil pelaksanaan pembaruan ZNT yang telah dilakukan, sebagai bentuk pertanggungjawaban administrasi dan dokumentasi kegiatan penilaian tanah. Laporan ini memuat proses, metode, hasil analisis, serta rekomendasi nilai tanah terbaru pada setiap zona, yang digunakan sebagai bahan evaluasi, pengambilan kebijakan, dan pendukung layanan pertanahan. Kegiatan ini meliputi: 1. Pengolahan dan kompilasi hasil pembaruan Peta ZNT; 2. Penyusunan narasi metodologi dan analisis nilai tanah; 3. Penyajian peta dan tabel nilai tanah per zona; 4. Penyusunan kesimpulan dan rekomendasi; 5. Finalisasi dan pengesahan laporan.', 'a. Sistematika Laporan • Pendahuluan; • Dasar hukum dan metodologi; • Gambaran umum wilayah; • Proses pembaruan Peta ZNT; • Hasil dan analisis nilai tanah; • Kesimpulan dan rekomendasi; • Lampiran peta dan data pendukung. b. Ketentuan Penyusunan • Laporan disusun berdasarkan data valid dan hasil pembaruan terbaru; • Menggunakan format dan pedoman teknis ATR/BPN; • Bahasa resmi dan dapat dipertanggungjawabkan secara administratif; • Memuat tanggal, wilayah, dan tim pelaksana kegiatan. c. Output/Hasil • Dokumen laporan Pembaruan Peta ZNT; • Peta Zona Nilai Tanah hasil pembaruan; • Tabel nilai tanah per zona; • Arsip fisik dan/atau digital. d. Media dan Format • Laporan cetak dan/atau digital (PDF); • Peta dalam format digital dan cetak; • Data terintegrasi dengan sistem informasi pertanahan. e. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang Peta Zona Nilai Tanah; • Pedoman teknis penilaian tanah ATR/BPN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1236271);
