INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966334', 63966334, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Persiapan Pembaruan Peta Zona Nilai Tanah', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 5760000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pembaruan Peta Zona Nilai Tanah merupakan kegiatan pemutakhiran data nilai tanah pada suatu wilayah berdasarkan perkembangan harga pasar tanah terkini, kondisi sosial ekonomi, serta perubahan penggunaan dan pemanfaatan tanah. Kegiatan ini bertujuan untuk menyediakan informasi nilai tanah yang akurat, mutakhir, dan dapat dipertanggungjawabkan sebagai dasar pelayanan pertanahan, perencanaan, dan kebijakan pertanahan. Kegiatan ini meliputi: 1. Pengumpulan dan analisis data transaksi dan/atau penawaran harga tanah; 2. Survei lapangan dan wawancara narasumber; 3. Analisis faktor-faktor penentu nilai tanah; 4. Penyesuaian batas zona nilai tanah; 5. Penyusunan dan penetapan pembaruan Peta ZNT.', 'a. Data dan Metodologi 1. Data transaksi/penawaran tanah yang valid dan representatif; 2. Analisis nilai tanah menggunakan pendekatan pasar; 3. Penyesuaian zona berdasarkan keseragaman karakteristik nilai tanah. b. Ketentuan Pelaksanaan 1. Survei lapangan dilakukan pada wilayah yang mengalami perubahan signifikan nilai tanah; 2. Penentuan zona memperhatikan aksesibilitas, peruntukan ruang, dan perkembangan wilayah; 3. Proses pembaruan dilaksanakan sesuai pedoman teknis ATR/BPN; 4. Validasi hasil dilakukan sebelum penetapan. c. Output/Hasil 1. Peta Zona Nilai Tanah (ZNT) hasil pembaruan; 2. Daftar nilai tanah per zona; 3. Basis data nilai tanah dalam bentuk digital; 4. Arsip administrasi pertanahan. d. Media dan Format 1. Peta digital (shapefile/geodatabase) dan/atau cetak; 2. Skala peta disesuaikan dengan ketentuan teknis; 3. Data terintegrasi dengan sistem informasi pertanahan. e. Dasar Hukum 1. Undang-Undang Nomor 5 Tahun 1960 (UUPA); 2. PP Nomor 18 Tahun 2021; 3. Peraturan Menteri ATR/BPN tentang Peta Zona Nilai Tanah; 4. Pedoman teknis penilaian tanah ATR/BPN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1237374);
