INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966588', 63966588, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penerbitan Sertipikat (SHAT Redistribusi Tanah)', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 2600000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Penerbitan Sertipikat (SHAT Redistribusi Tanah) merupakan kegiatan pelayanan pertanahan dalam rangka penerbitan sertipikat hak atas tanah berdasarkan Surat Keputusan Redistribusi Tanah dan/atau SHAT Redistribusi Tanah sebagai bagian dari pelaksanaan Reforma Agraria. Kegiatan ini bertujuan memberikan kepastian hukum dan perlindungan hukum kepada subjek penerima redistribusi tanah melalui penerbitan sertipikat yang sah. Kegiatan ini meliputi: • Penelitian akhir kelengkapan berkas redistribusi tanah; • Pembukuan hak dalam buku tanah; • Pencetakan sertipikat hak atas tanah; • Penandatanganan sertipikat oleh pejabat yang berwenang; • Pengadministrasian, pengarsipan, dan penyerahan sertipikat kepada penerima hak.', 'a. Persyaratan Objek dan Subjek • Objek: bidang tanah hasil redistribusi tanah yang telah ditetapkan; • Subjek: penerima redistribusi tanah yang sah; • Data fisik dan data yuridis telah disahkan melalui SHAT Redistribusi Tanah. b. Ketentuan Pelaksanaan • Pembukuan hak dilakukan sesuai ketentuan pendaftaran tanah; • Sertipikat diterbitkan berdasarkan data fisik dan yuridis yang telah diverifikasi; • Proses penerbitan mengikuti SOP Redistribusi Tanah; • Pelayanan dilaksanakan secara tertib, transparan, dan akuntabel. c. Output/Hasil • Sertipikat Hak Milik hasil redistribusi tanah; • Buku Tanah; • Surat Ukur/Peta Bidang Tanah; • Arsip administrasi pertanahan dalam bentuk fisik dan/atau digital. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • PP Nomor 18 Tahun 2021; • Peraturan Presiden Nomor 62 Tahun 2023 tentang Percepatan Reforma Agraria; • Peraturan Menteri ATR/BPN tentang Redistribusi Tanah dan Pendaftaran Tanah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1237905);
